from uuid import uuid4

import config
import database
import uniclubs_catalog
import uniclubs_database
import uniclubs_user


def profile_key(connection, user_id):
    """Return a stable private owner token that is replaced when the app profile is reset."""
    if type(user_id) is not int or user_id < 1:
        raise ValueError('A valid profile is required for private UniClubs planning.')
    row = connection.execute('SELECT id FROM users WHERE id=?', (user_id,)).fetchone()
    if row is None:
        raise ValueError('The profile was not found.')
    setting = f'uniclubs_profile_{user_id}'
    owner = database.get_setting(connection, setting)
    if owner is None:
        if connection.in_transaction:
            raise ValueError('Finish the current transaction before creating a planning owner.')
        # A reset may reuse user ID 1; a fresh token prevents the new user inheriting old plans.
        # A concurrent tab may already have inserted a token after our first read.
        with connection:
            connection.execute('''INSERT INTO app_settings (key,value) VALUES (?,?)
                ON CONFLICT(key) DO NOTHING''', (setting, uuid4().hex))
        owner = database.get_setting(connection, setting)
    if not isinstance(owner, str) or not owner.strip():
        raise ValueError('The private UniClubs planning owner is invalid.')
    return owner


def _catalog_call(function, *args):
    """Open, initialize and close the public catalog around one small operation."""
    catalog = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
    try:
        uniclubs_database.init_db(catalog)
        return function(catalog, *args)
    finally:
        catalog.close()


def _user_call(connection, user_id, function, *args, **kwargs):
    """Route one operation to this profile's ignored private planning database."""
    owner = profile_key(connection, user_id)
    private = uniclubs_user.get_connection(config.UNICLUBS_USER_DB_FILE)
    try:
        uniclubs_user.init_db(private)
        return function(private, owner, *args, **kwargs)
    finally:
        private.close()


def get_profile(connection, user_id=None):
    """Read the app profile and add independent source favorites to its copied sets."""
    if user_id is None:
        user_id = database.get_current_user_id(connection)
    profile = database.get_user_profile(connection, user_id)
    favorites = _user_call(connection, user_id, uniclubs_user.get_favorites)
    profile.favorite_series_ids.update(favorites['series'])
    profile.favorite_club_ids.update(favorites['club'])
    return profile


def load_events(start, end):
    """Read source events for a naive Zurich interval from the independent catalog."""
    return _catalog_call(uniclubs_catalog.events_between, start, end)


def load_event(event_id):
    """Read one namespaced source event without querying the legacy event table."""
    return _catalog_call(uniclubs_catalog.get_event, event_id)


def date_bounds():
    """Return the source catalog's date bounds, or (None, None) when it is empty."""
    return _catalog_call(uniclubs_catalog.date_bounds)


def get_interaction(connection, user_id, event_id):
    """Return only this profile's private interaction for one namespaced source event."""
    if not uniclubs_catalog.is_catalog_id(event_id):
        raise ValueError('A namespaced UniClubs event ID is required.')
    return _user_call(connection, user_id, uniclubs_user.get_interaction, event_id)


def save_interaction(connection, user_id, event_id, action, rating=None, now=None):
    """Save a validated source action privately; never forward it to the legacy API."""
    event = load_event(event_id)
    if event is None:
        raise ValueError('The UniClubs event was not found.')
    return _user_call(connection, user_id, uniclubs_user.save_interaction,
                      user_id, event, action, rating=rating, now=now)


def _favorite_exists(kind, target_id):
    """Check that a new series or club favorite refers to the independent public catalog."""
    if not isinstance(target_id, str):
        return False
    if kind == 'series' and target_id.startswith('uniclubs-series:'):
        return load_event('uniclubs:' + target_id[len('uniclubs-series:'):]) is not None
    if kind != 'club' or not target_id.startswith('uniclubs-club:'):
        return False
    catalog = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
    try:
        uniclubs_database.init_db(catalog)
        return catalog.execute('SELECT id FROM clubs WHERE external_id=?',
                               (target_id[len('uniclubs-club:'):],)).fetchone() is not None
    finally:
        catalog.close()


def set_favorite(connection, user_id, kind, target_id, enabled):
    """Save or remove a source favorite; category favorites remain the app's shared setting."""
    if type(enabled) is not bool:
        raise ValueError('The favorite must be enabled or disabled explicitly.')
    if enabled and not _favorite_exists(kind, target_id):
        raise ValueError('The UniClubs favorite target was not found.')
    return _user_call(connection, user_id, uniclubs_user.set_favorite,
                      kind, target_id, enabled)


def plans(connection, user_id):
    """Return available source events and this owner's saved actions in chronological order."""
    interactions = _user_call(connection, user_id, uniclubs_user.list_interactions)
    catalog = uniclubs_database.get_connection(config.UNICLUBS_DB_FILE)
    result = []
    try:
        uniclubs_database.init_db(catalog)
        for interaction in interactions:
            try:
                event = uniclubs_catalog.get_event(catalog, interaction['event_id'])
            except ValueError:
                event = None
            if event is not None:
                result.append((event, interaction))
    finally:
        catalog.close()
    return sorted(result, key=lambda item: (item[0].start, item[0].event_id))


def confirmed_events(connection, user_id, start, end):
    """Return known-time, single-day source plans overlapping the requested calendar range."""
    result = []
    for event, interaction in plans(connection, user_id):
        if interaction['status'] not in ('confirmed', 'attended', 'not_attended'):
            continue
        if event.source_cancelled or event.is_multi_day() or event.end_is_estimated:
            continue
        if event.start < end and event.end > start:
            result.append(event)
    return result


def known_event_ids(connection, user_id):
    """Recognize locally owned source exports even after a plan has been cancelled."""
    rows = _user_call(connection, user_id, uniclubs_user.list_interactions)
    return {row['event_id'] for row in rows}


def calendar_uncertain(connection, user_id, start, end):
    """Refuse a fit guarantee when an active saved source plan has no dependable interval."""
    rows = _user_call(connection, user_id, uniclubs_user.list_interactions)
    for row in rows:
        if row['status'] != 'confirmed':
            continue
        try:
            event = load_event(row['event_id'])
        except (ValueError, TypeError, OverflowError):
            return True
        if event is None:
            return True
        if event.source_cancelled:
            continue
        if (event.start < end and event.end > start
                and (event.end_is_estimated or event.is_multi_day())):
            return True
    return False


def pending_feedback(connection, user_id, now=None):
    """Return ended source plans awaiting attendance or a rating, oldest ending first."""
    now = config.local_now(now)
    pending = []
    for event, interaction in plans(connection, user_id):
        if (event.end >= now or event.source_cancelled
                or event.end_is_estimated or event.is_multi_day()):
            continue
        if (interaction['status'] == 'confirmed'
                or (interaction['status'] == 'attended' and interaction['rating'] is None)):
            row = interaction.copy()
            row.update({'title': event.title, 'start_time': database.to_db_text(event.start),
                        'end_time': database.to_db_text(event.end), 'is_demo': 0})
            pending.append(row)
    return sorted(pending, key=lambda row: (row['end_time'], row['event_id']))


def get_rating_revision(connection):
    """Read the current local profile's source revision, or zero before onboarding."""
    user_id = database.get_current_user_id(connection)
    if user_id is None:
        return 0
    return _user_call(connection, user_id, uniclubs_user.get_revision)


def _rated_plans(connection, user_id, now):
    """Select available attended source ratings while excluding no-shows and future answers."""
    cutoff = database.to_db_text(now)
    result = []
    for event, interaction in plans(connection, user_id):
        answered = interaction.get('answered_at')
        if (interaction['status'] == 'attended' and interaction['rating'] is not None
                and event.end < now and not event.source_cancelled
                and not event.end_is_estimated and not event.is_multi_day()
                and answered is not None and answered <= cutoff):
            result.append((event, interaction))
    return result


def training_examples(connection, now=None):
    """Return genuine current-user source examples for optional shared-model training."""
    user_id = database.get_current_user_id(connection)
    if user_id is None:
        return []
    now = config.local_now(now)
    profile = get_profile(connection, user_id)
    return [{'event': event, 'profile': profile, 'rating': interaction['rating'],
             'answered_at': interaction.get('answered_at')}
            for event, interaction in _rated_plans(connection, user_id, now)]


def bundle_averages(connection, user_id, now=None):
    """Combine eligible legacy and private source ratings without averaging averages."""
    now = config.local_now(now)
    stamp = database.to_db_text(now)
    rows = connection.execute('''SELECT b.key, i.rating FROM interactions i
        JOIN events e ON e.id=i.event_id JOIN series s ON s.id=e.series_id
        JOIN bundles b ON b.id=s.bundle_id
        WHERE i.user_id=? AND i.status='attended' AND i.rating IS NOT NULL
        AND e.end_time<? AND (i.answered_at IS NULL OR i.answered_at<=?)''',
                              (user_id, stamp, stamp)).fetchall()
    totals = {}
    for row in rows:
        total, count = totals.get(row['key'], (0, 0))
        totals[row['key']] = total + row['rating'], count + 1
    for event, interaction in _rated_plans(connection, user_id, now):
        total, count = totals.get(event.bundle_key, (0, 0))
        totals[event.bundle_key] = total + interaction['rating'], count + 1
    return {key: total / count for key, (total, count) in totals.items()}


def clear_current_user(connection):
    """Delete this owner's private source state before the app's explicit profile reset."""
    user_id = database.get_current_user_id(connection)
    if user_id is None:
        return
    owner = database.get_setting(connection, f'uniclubs_profile_{user_id}')
    if owner is None:
        return
    private = uniclubs_user.get_connection(config.UNICLUBS_USER_DB_FILE)
    try:
        uniclubs_user.init_db(private)
        uniclubs_user.clear_owner(private, owner)
    finally:
        private.close()
